const test=`import assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport path from 'node:path';\nconst root=process.cwd();\nconst read=(p)=>JSON.parse(fs.readFileSync(path.join(root,p),'utf8'));\nconst exists=(p)=>fs.existsSync(path.join(root,p));\nconst course=read('content/courses/COURSE-LH-TECH1-005.json');\nassert.equal(course.status,'draft');assert.equal(course.finalAssessment,'ASSESS-LH-TECH1-005-FINAL');assert.ok(course.modules.includes('MOD-LH-TECH1-005-CROPCARE'));assert.equal(course.extensions?.dedicatedCourseAssessmentRequired,false);assert.equal(course.extensions?.dedicatedPerformanceValidationRequired,true);assert.deepEqual(course.extensions?.mappedPracticals,['PRACTICAL-TECH1-C','PRACTICAL-TECH1-D','PRACTICAL-TECH1-E']);assert.equal(course.extensions?.pesticideApplicatorAuthorityConferred,false);assert.equal(course.extensions?.dedicatedItemCount,36);\nconst module=read('content/modules/MOD-LH-TECH1-005-CROPCARE.json');assert.equal(module.lessons.length,4);for(const id of module.lessons){assert.ok(exists(\`content/lessons/\${id}.json\`));const l=read(\`content/lessons/\${id}.json\`);assert.ok(l.estimatedMinutes>=45);for(const o of l.learningObjectives)assert.ok(exists(\`content/learning-objectives/\${o}.json\`));}\nconst formative=read('content/assessments/ASSESS-LH-TECH1-005-M01.json');const final=read('content/assessments/ASSESS-LH-TECH1-005-FINAL.json');assert.equal(formative.items.length,12);assert.equal(final.items.length,24);assert.equal(new Set([...formative.items,...final.items]).size,36);assert.deepEqual(final.extensions?.linkedCredentialPracticals,['PRACTICAL-TECH1-C','PRACTICAL-TECH1-D','PRACTICAL-TECH1-E']);\nconst objectives=new Map(final.objectives.map(x=>[x,0]));const keys=[0,0,0,0];let high=0;for(const id of final.items){const q=read(\`content/questions/\${id}.json\`);assert.equal(q.purpose,'summative');assert.ok(q.references.length);assert.ok(final.competencies.includes(q.competency));assert.ok(final.objectives.includes(q.objective));objectives.set(q.objective,objectives.get(q.objective)+1);keys[q.correct]++;if(['apply','analyze','evaluate','create'].includes(q.bloomLevel))high++;}for(const [id,n] of objectives)assert.equal(n,4,\`\${id} should have four summative items; found \${n}\`);assert.ok(high>=20);assert.ok(Math.max(...keys)<=6,\`unbalanced key positions: \${keys}\`);for(const id of formative.items){const q=read(\`content/questions/\${id}.json\`);assert.equal(q.purpose,'formative');}\nconsole.log('Course 005 production slice passed: four lessons, six objectives, 12 distinct formative items and 24 balanced summative items are draft-wired with PRACTICAL-TECH1-C/D/E mapping and no pesticide-applicator claim.');\n`;
